 function click(e){const scenario=e.target.closest('[data-scenario]');if(scenario){s.scenario=scenario.dataset.scenario;reset();return}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;if(a==='theme'){s.theme=s.theme==='light'?'dark':'light';render()}if(a==='settings'){s.settings=!settingsOpen();render()}if(a==='leave'){onLeave();return}if(a==='starter'){s.draft=b.textContent;render();root.querySelector('[name=draft]').focus()}if(a==='retry')send(true);if(a==='edit')edit();if(a==='cancel')edit(true);if(a==='mic'){if(voice?.listen&&engine.voice?.().listen){s.state='listening';render();const token=epoch;stopVoice=voice.listen({lang:s.target,ui:s.ui,scenario:s.scenario,onText:text=>{if(token!==epoch||disposed)return;s.draft=String(text).slice(0,max());s.notice=t().voiceHint;render()},onEnd:()=>{if(token===epoch&&!disposed){s.state='idle';render()}},onError:error=>{if(token===epoch&&!disposed){s.state='idle';s.notice=error?.code==='micDenied'?t().micDenied:t().noVoice;render()}}})}else{s.notice=t().noVoice;render()}}if(a==='speak'){const reply=b.dataset.i?s.messages[+b.dataset.i]:[...s.messages].reverse().find(m=>m.role==='assistant');if(voice?.speak&&engine.voice?.().speak&&reply){s.state='speaking';render();const token=epoch;stopVoice=voice.speak(reply.content,s.target,()=>{if(token===epoch&&!disposed){s.state='idle';render()}})}else{s.notice=t().noVoice;render()}}if(a==='help')getHelp();if(a==='another'&&s.practice)getHelp(s.practice.corrected);
 if(a==='practise'){const c=s.messages[+b.dataset.i]?.result?.correction;if(c){s.practice={corrected:c.corrected,draft:'',status:''};s.help=null;s.helpError=false;render();scrollEnd();root.querySelector('[name=practice]')?.focus({preventScroll:true})}}
 if(a==='closePractice'){s.practice=null;s.help=null;render();scrollEnd()}
 if(a==='use'){const x=s.help?.examples[+b.dataset.k];if(x){s.draft=x.text.slice(0,max());s.help=null;s.practice=null;render();scrollEnd();root.querySelector('[name=draft]')?.focus()}}
 if(a==='report'&&report){const m=s.messages[+b.dataset.i];if(m)report.send(m)}if(a==='forget'&&memory){memory.forget();render()}if(a==='stop'){epoch++;stopVoice?.();stopVoice=null;s.state=s.messages.length?'idle':'welcome';render()}}
 function change(e){const n=e.target.name;if(n==='style'){s.style=e.target.value;s.notice=t().styleChanged;onStyle?.(s.style);render()}if(n==='autoVoice'){s.autoVoice=e.target.checked;onAutoVoice?.(s.autoVoice);if(!s.autoVoice){stopVoice?.();stopVoice=null}render()}if(['ui','target','level','scene'].includes(n)){s[n]=e.target.value;reset()}if(n==='preview')preview(e.target.value);if(n==='errorCode'){s.errorCode=e.target.value;preview('error',e.target.value)}}
 function input(e){if(e.target.name==='practice'&&s.practice){s.practice.draft=e.target.value;return}if(e.target.name==='draft'){s.draft=e.target.value;root.querySelector('#counter').textContent=`${s.draft.length}/${max()} ${t().count}`;root.querySelector('[type=submit]').disabled=!s.draft.trim()||s.busy||!!s.pending||s.until>Date.now()}}
 function submit(e){e.preventDefault();if(e.target.closest?.('.ac-repeat')){const p=s.practice,v=root.querySelector('[name=practice]')?.value||'';if(p&&v.trim()){p.draft=v;p.status=normalize(v)===normalize(p.corrected)?'ok':'again';render()}return}if(matchMedia('(pointer:coarse)').matches)root.querySelector('[name=draft]')?.blur();send()} // TEST-033: on a phone the keyboard closes after sending (owner's request); on desktop the focus stays in the field
 root.addEventListener('click',click);root.addEventListener('change',change);root.addEventListener('input',input);root.addEventListener('submit',submit);bind();render();if(s.messages.length)scrollEnd();refreshCooldown();
 return{preview,getState:()=>{const messages=s.messages.map(m=>({...m}));return {...s,messages,pending:messages[s.messages.indexOf(s.pending)]||null}},destroy(){disposed=true;viewport?.removeEventListener('resize',resizeViewport);viewport?.removeEventListener('scroll',resizeViewport);root.removeEventListener('scroll',trackEnd,true);root.style.removeProperty('--lexi-viewport-height');root.style.removeProperty('--lexi-viewport-top');root.classList.remove('lexi-keyboard');epoch++;unsub?.();clearInterval(interval);stopVoice?.();root.removeEventListener('click',click);root.removeEventListener('change',change);root.removeEventListener('input',input);root.removeEventListener('submit',submit);root.replaceChildren()}};
